"use client";

import { Canvas, useFrame } from "@react-three/fiber";
import { useRef } from "react";
import * as THREE from "three";

const GradientShader = {
  uniforms: {
    uTime: { value: 0 },
    uColor1: { value: new THREE.Color("#1a103c") }, // Dark Purple
    uColor2: { value: new THREE.Color("#4a1d96") }, // Vivid Violet
    uColor3: { value: new THREE.Color("#000000") }, // Black
    uColor4: { value: new THREE.Color("#1e1b4b") }, // Deep Blue
  },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColor1;
    uniform vec3 uColor2;
    uniform vec3 uColor3;
    uniform vec3 uColor4;
    varying vec2 vUv;

    // Simplex 2D noise
    vec3 permute(vec3 x) { return mod(((x*34.0)+1.0)*x, 289.0); }
    float snoise(vec2 v){
      const vec4 C = vec4(0.211324865405187, 0.366025403784439,
               -0.577350269189626, 0.024390243902439);
      vec2 i  = floor(v + dot(v, C.yy) );
      vec2 x0 = v -   i + dot(i, C.xx);
      vec2 i1;
      i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
      vec4 x12 = x0.xyxy + C.xxzz;
      x12.xy -= i1;
      i = mod(i, 289.0);
      vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
      + i.x + vec3(0.0, i1.x, 1.0 ));
      vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
      m = m*m ;
      m = m*m ;
      vec3 x = 2.0 * fract(p * C.www) - 1.0;
      vec3 h = abs(x) - 0.5;
      vec3 ox = floor(x + 0.5);
      vec3 a0 = x - ox;
      m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
      vec3 g;
      g.x  = a0.x  * x0.x  + h.x  * x0.y;
      g.yz = a0.yz * x12.xz + h.yz * x12.yw;
      return 130.0 * dot(m, g);
    }

    void main() {
      vec2 uv = vUv;
      float time = uTime * 0.2;
      
      // Create a flowing noise pattern
      float noise1 = snoise(uv * 3.0 + vec2(time * 0.5, time * 0.3));
      float noise2 = snoise(uv * 1.5 - vec2(time * 0.2, time * 0.4));
      
      // Mix noise
      float pattern = (noise1 + noise2) * 0.5;
      
      // Radial glow/beam effect
      float dist = length(uv - vec2(0.5, 0.5));
      float beam = 1.0 - smoothstep(0.2, 1.2, dist + pattern * 0.2);
      
      // Mix colors based on pattern and position
      vec3 color = mix(uColor3, uColor4, uv.y); // Vertical gradient background
      color = mix(color, uColor1, smoothstep(0.3, 0.7, pattern + 0.5)); // Add chaotic purple
      color = mix(color, uColor2, beam * 1.5); // Add bright center beam
      
      gl_FragColor = vec4(color, 1.0);
    }
  `,
};

function GradientMesh() {
  const mesh = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (mesh.current) {
      // Safe access to uniforms
      const material = mesh.current.material as THREE.ShaderMaterial;
      if (material.uniforms) {
        material.uniforms.uTime.value = state.clock.getElapsedTime();
      }
    }
  });

  return (
    <mesh ref={mesh} position={[0, 0, 0]} scale={[10, 10, 1]}>
      <planeGeometry args={[2, 2, 32, 32]} />
      <shaderMaterial
        args={[GradientShader]}
        transparent={true}
        depthWrite={false}
      />
    </mesh>
  );
}

export function NeuralBackground() {
  return (
    <div className="absolute inset-0 -z-10 w-full h-full">
      <Canvas
        camera={{ position: [0, 0, 1], fov: 75 }}
        gl={{ antialias: true, alpha: true }}
      >
        <GradientMesh />
      </Canvas>
    </div>
  );
}
